style.css:
@-moz-document domain("wunderground.com") {
/*
   * Weather Underground is an Angular Material SPA with colors hardcoded
   * per-element (no CSS custom properties to remap). We retheme by overriding
   * stable Material / semantic selectors: app-root, .region-content-top,
   * .data-module, .current-container, .list-container, mat-sidenav-*,
   * .global-header/.topbar, the mat tables, etc. There are no hashed class
   * names to chase.
   *
   * HANDS OFF the weather data itself: radar/satellite maps, the wundermap,
   * canvas/leaflet tiles, temperature scales, condition icons (sun/cloud/rain),
   * alert banners and precip/UV color codes are left intact -- we only theme
   * the surrounding chrome, surfaces, text and borders.
   */
  :root {
    color-scheme: dark;

    --wu-base: #14181d;          /* page base                     */
    --wu-surface: #1c2128;       /* cards / modules               */
    --wu-surface-2: #161d27;     /* alt elevated / zebra          */
    --wu-chrome: #0d1117;        /* header / footer / sidenav     */
    --wu-border: #262c33;        /* subtle border                 */
    --wu-border-2: #2d333b;      /* component border              */
    --wu-text: #e6edf3;          /* primary text                  */
    --wu-text-2: #c4cdd6;        /* body text                     */
    --wu-text-muted: #8b949e;    /* metadata / muted              */
    --wu-link: #5fb0e6;          /* refined WU blue for dark      */
    --wu-link-hover: #9bd4ff;
  }

  /* ---- base ------------------------------------------------------------- */
  html,
  body,
  body.enable-sda,
  app-root,
  mat-sidenav-container,
  .mat-drawer-container,
  .mat-sidenav-container,
  .mat-drawer-content,
  .mat-sidenav-content {
    background-color: var(--wu-base) !important;
    color: var(--wu-text-2) !important;
  }

  /* Soften every light border to a subtle dark one. Specific brighter ones
     (e.g. the #4c4c4c table grid) are re-handled below. */
  * {
    border-color: var(--wu-border) !important;
  }

  /* ---- header / chrome -------------------------------------------------- */
  .topbar,
  .global-header,
  wu-header .topbar,
  wu-header .global-header,
  mat-toolbar,
  .mat-toolbar {
    background-color: var(--wu-chrome) !important;
    color: var(--wu-text) !important;
  }

  /* side navigation drawer */
  mat-sidenav,
  .mat-drawer,
  .mat-sidenav,
  .sidenav-main-menu {
    background-color: var(--wu-chrome) !important;
    color: var(--wu-text-2) !important;
  }

  /* ---- content regions & cards ----------------------------------------- */
  .region-content-top,
  .region-content-bottom,
  .region-content,
  .has-content,
  section.inner-content,
  .inner-content,
  mat-sidenav-content > div {
    background-color: var(--wu-base) !important;
  }

  /* Foundation grid scaffolding anywhere in the content area carries its own
     white / light-grey bg. Blanket it transparent so it inherits the dark base
     or the surface of an enclosing card; images/maps/charts excluded below. */
  mat-sidenav-content .row,
  mat-sidenav-content .columns,
  lib-city-current-conditions,
  .city-conditions,
  .conditions-circle-wrap,
  .conditions-circle,
  .condition-data,
  .conditions-extra {
    background-color: transparent !important;
  }

  /* Module / card surfaces. WU wraps each module in a lib-* web component and
     a .data-module; the small dashboard tiles use lib-*-tile wrappers. */
  .data-module,
  .current-container,
  .list-container,
  .module,
  .city-almanac,
  .city-astronomy,
  .additional-conditions,
  .video-promo,
  .removeIfEmpty,
  .weather-map,
  .city-map,
  .city-map-wrapper,
  lib-precip-tile,
  lib-pollen-tile,
  lib-air-quality-tile,
  lib-uv-tile,
  lib-city-today-forecast,
  lib-additional-conditions,
  lib-almanac,
  .tile-title,
  mat-card,
  .mat-mdc-card,
  .mat-card,
  .panel,
  .card {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }

  /* The Foundation grid scaffolding (.row / .columns / .small-* / .medium-*)
     carries its own white / light-grey backgrounds inside these regions. Make
     the scaffolding transparent so it inherits the dark surface, while images,
     maps and charts (handled at the bottom) are never touched. */
  .region-content-top .row,
  .region-content-top .columns,
  .region-content-bottom .row,
  .region-content-bottom .columns,
  .current-container *:not(img):not(svg):not(canvas):not(picture),
  .list-container *:not(img):not(svg):not(canvas):not(picture),
  .data-module *:not(img):not(svg):not(canvas):not(picture):not(.module-header),
  .city-forecast .row,
  .city-forecast .columns,
  .inner-content > .row,
  .forecast-tile,
  .day-content {
    background-color: transparent !important;
  }

  /* Map tabs bar (.ui-tabs.header-tabs #f7f7f7) above the city map. */
  .ui-tabs,
  .header-tabs,
  .wundermap_links {
    background-color: var(--wu-surface-2) !important;
  }

  /* The little dashboard tiles label bar (.tile-title #e7e7e7) -> elevated. */
  .tile-title {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* Module header strip (#e7e7e7 with #4c4c4c text). */
  .module-header,
  .data-module .module-header {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* re-establish opaque surfaces on the table header / zebra inside modules */
  .data-module thead th,
  .data-module .mat-mdc-header-cell {
    background-color: var(--wu-chrome) !important;
  }

  /* ---- text ------------------------------------------------------------- */
  h1, h2, h3, h4, h5, h6,
  .module-title,
  .city-header,
  .current-temp,
  b, strong {
    color: var(--wu-text) !important;
  }

  p, span, li, td, th, dt, dd, label, figcaption, small,
  .data-module *,
  .current-container * {
    color: inherit;
  }

  /* WU hardcodes its standard body text as rgba(0,0,0,.87) and #1e2023 on most
     grid/content blocks -- lift these to light. Inline-styled greys too. */
  .region-content-top,
  .region-content-top .row,
  .region-content-top .columns,
  .city-conditions,
  .conditions-extra,
  .city-header,
  .data-module .content,
  [style*="color: rgb(76, 76, 76)"],
  [style*="color:#4c4c4c"],
  [style*="color: rgb(102, 102, 102)"] {
    color: var(--wu-text-2) !important;
  }

  /* Muted greys WU uses for secondary labels (#696969, #4c4c4c on captions). */
  .duration,
  .columns .duration,
  .mat-mdc-tooltip-trigger,
  .phases-name,
  .module-footer,
  .attribution,
  .branding,
  .last-updated,
  .split,
  .separator {
    color: var(--wu-text-muted) !important;
  }

  /* Dark class-driven text WU renders in #4c4c4c / #1e2023 (not inline-styled,
     so the [style*=] catch above misses them): day labels, the daily summary
     paragraph, astronomy labels. Lift to readable body text. */
  .day,
  .weather-quickie,
  .astro-data,
  .obs-date,
  .obs-text,
  .calendar-day,
  .timestamp {
    color: var(--wu-text-2) !important;
  }
  /* Home/forecast hourly strip date row (.forecast .dates span) is WU's dim
     #696969 grey -> ~2:1 dark-on-dark. Lift to the readable muted light. */
  .forecast .dates span,
  .forecast .dates .date,
  .forecast .times span {
    color: var(--wu-text-muted) !important;
  }

  /* Astronomy sunrise/sunset accent (#cc5500 / #e59900) -> readable amber. WU now
     colours these by CLASS (.sunrise-icon / .sunset-icon) instead of the old inline
     style, so the [style*="204"] catch no longer matches and the generic .astro-data
     grey lift flattened the sunrise/sunset TIMES to plain grey. Match the classes so
     the amber reads; moonrise/moonset stay grey (they are natively grey). */
  .astro-data[style*="204"],
  .astro-data.sunrise-icon,
  .astro-data.sunset-icon,
  .sun-data,
  .moon-data {
    color: #ffb454 !important;
  }

  /* WU's data values use a hardcoded near-black (#1e2023) as the NEUTRAL color,
     reserving saturated hues (red highs, orange current temp, blue precip, grey
     lows) for the SEMANTIC temperature/precip scale. We lift only the neutral
     default to light text and KEEP the saturated scale colors below, so the
     temperature scale stays meaningful. WU's own selectors used verbatim. */
  .data-module .content .data-point,
  .data-module .content .wx-value,
  .data-module .content .wu-value,
  .wind-dir .wx-value,
  #stationselector_table .table-row .temp,
  .location-data,
  .wu-value,
  .wu-suffix,
  .wu-degree,
  .wx-value,
  .data-point {
    color: var(--wu-text) !important;
  }

  /* KNOWN TRADE-OFF: the station-nav readout next to the city name
     (`.station-nav .station-name .wu-value`) carries an INLINE colour WU
     computes from its full temperature scale (e.g. `color:#da2f2f` when hot).
     The lift above erases it. Letting the inline value through instead is
     unsafe: the cold end of that scale is a dark blue/purple that would be
     near-invisible on the dark base, and the colour is dynamic so no fixed
     remap is correct. The same reading is shown, in scale colour, by the
     conditions circle directly below, so the neutral lift stays. */

  /* Brighten the dark teal-blue link/precip accent (#006f9e) for dark. */
  .data-module .content a .data-point,
  .data-module .content a .wx-value,
  .data-module .content a .wu-value {
    color: var(--wu-link) !important;
  }
  /* The Material data tables (hourly / 10-day) are NOT wrapped in
     `.data-module .content`, so the rule above never reached them: every precip
     link rendered its digits in the plain value white while the unit beside it
     stayed link blue. Let anything inside a table-cell link inherit the anchor's
     colour so the whole link reads as one. */
  td a .wu-value,
  td a .wu-label,
  td a .wu-degree,
  td a .wu-suffix,
  td a .wx-value,
  td a .data-point,
  a.hook .wu-value,
  a.hook .wu-label,
  a.hook .wu-degree,
  a.hook .wu-suffix {
    color: inherit !important;
  }

  /* Header city-conditions readout ("61° Cloudy" by the city name) uses a
     more specific #4c4c4c rule than the generic .wu-value lift -- match it. */
  .city-info,
  .city-info .wu-value,
  .city-info .wu-suffix,
  .city-info .wu-degree,
  .city-info .wu-label,
  .city-info span,
  .city-conds,
  .city-conds .wu-value,
  .city-conds span {
    color: var(--wu-text) !important;
  }

  /* Re-assert the SEMANTIC scale colors (these read fine on dark) so the
     blanket lift above doesn't flatten them: orange current temp, grey lows. */
  .current-temp,
  .conditions-circle .current-temp,
  .feels-like .temp {
    color: #ff9d4d !important;          /* WU orange, nudged lighter for dark */
  }
  /* The forecast tiles read "HIGH 83 | 71 °F": WU paints the high its neutral
     body colour and the LOW its secondary grey (#8a8a8a). The blanket .wu-value
     lift above reaches INSIDE .secondary-temp, so the low rendered as bright as
     the high and the pair read as two identical numbers. The wrapper alone is not
     enough -- the value/label/degree spans each need the muted colour. */
  .temp .secondary-temp,
  .temp .secondary-temp .wu-value,
  .temp .secondary-temp .wu-label,
  .temp .secondary-temp .wu-degree,
  .temp .secondary-temp .wu-suffix {
    color: var(--wu-text-muted) !important;  /* low/secondary temp grey */
  }
  /* 10-day / calendar temperature scale: keep the warm reds/oranges (readable
     on dark) but lift the cold blue end (#0053ae is too dark on dark). */
  .temp-lo,
  .temp-low,
  .wu-value.temp-lo {
    color: #4d9fe6 !important;          /* cold blue, lightened for dark */
  }
  .temp-hi,
  .temp-high {
    color: #ff6b6b !important;          /* warm red, lightened for dark */
  }
  /* Other saturated high-temp scale values are kept as authored. */

  /* Muted / secondary labels (greys #696969 etc.). */
  /* `.show-for-medium` is deliberately NOT in this list: it is a Foundation
     responsive-visibility utility, not a colour role. WU puts it on the hourly
     table's whole Conditions column, the page heading and a .module-header
     .component-title, all of which are the SAME #4c4c4c as their neighbours --
     muting it invented a hierarchy the site does not have. */
  .subheading,
  .split,
  .date,
  .phase-name,
  .phases-date,
  .small-4,
  .wind-north,
  .module-title-small,
  .timestamp {
    color: var(--wu-text-muted) !important;
  }

  /* The mini-map's own zoom / play chips are native map chrome we deliberately
     leave as WU's translucent white pad -- but on /health the map sits INSIDE a
     .data-module, so the `.data-module *` neutralizer above zeroed the pad and
     left the cyan glyphs floating bare on the basemap while the identical
     control on the city page kept its chip. Restore the native fill; the
     neutralizer is (0,2,4), so this needs three class-level components. */
  .data-module .mini-map .zoomIn,
  .data-module .mini-map .zoomOut,
  .data-module .mini-map .mapPlay {
    background-color: rgba(247, 247, 247, 0.9) !important;
  }
  /* Those chips are outlined in WU's cyan and separated by a cyan divider; the
     blanket `*` reset flattens both to the theme line colour, so the pad we
     deliberately keep native loses the one thing that made it look native. */
  .zoomControl,
  .zoomControl .zoomOut,
  lib-animator-buttons .mapPlay {
    border-color: #15aadc !important;
  }

  /* Mapbox attribution overlay (white text on white pill) on the mini-map. */
  .__wxmap_MapboxAttribution,
  [class*="MapboxAttribution"] {
    color: var(--wu-text-muted) !important;
    background-color: rgba(13, 17, 23, 0.6) !important;
  }

  /* ---- links / accent --------------------------------------------------- */
  a,
  a:visited {
    color: var(--wu-link) !important;
  }
  a:hover,
  a:focus {
    color: var(--wu-link-hover) !important;
  }
  /* WU nests <b>/<strong> inside links (e.g. the hourly "20% / 0 in" precip
     links). The generic bold lift below would paint them plain text, stripping
     the link colour that is the only affordance -- keep them inheriting. */
  a b,
  a strong {
    color: inherit !important;
  }

  /* WU blue accents used as text (#006f9e / #19aadb) -> dark-friendly blue */
  .ui-tabs a,
  .header-tabs a,
  .wundermap_links a {
    color: var(--wu-link) !important;
  }
  /* The city-map RADAR/SATELLITE bar carries BOTH `ui-tabs-nav` and `tab-nav` on
     its <ul>, so the /health pollen-tab rule further down (`.tab-nav li a`, at
     (0,2,1)) out-specifies the (0,1,1) prelude above and painted the unselected
     tab plain body grey -- the "this is a tab you can click" cue, gone. Re-claim
     it at (0,3,1); the selected tab keeps its own white + underline treatment. */
  .ui-tabs .tab-nav li:not(.ui-state-active) a:not(.selected),
  .header-tabs .tab-nav li:not(.ui-state-active) a:not(.selected) {
    color: var(--wu-link) !important;
  }
  .ui-tabs a.selected,
  .header-tabs a.selected,
  .ui-tabs li.selected,
  .header-tabs li.selected,
  a.selected,
  a.selected span,
  .ui-tabs-nav .ui-state-active,
  .ui-tabs-nav .ui-state-active a,
  .wundermap_module_tabs .ui-state-active a,
  li.ui-state-active a {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
    border-color: var(--wu-border-2) !important;
  }

  /* ---- data tables (hourly / 10-day / history) -------------------------- */
  table,
  .mat-mdc-table,
  .mat-table,
  .mdc-data-table__table,
  tbody,
  tfoot,
  .mdc-data-table__content,
  .summary-table,
  .observation-table {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
    border-color: var(--wu-border) !important;
  }
  /* history "summary" table sets a #f9f9f9 bg on the bare thead element; the
     Material tables paint the same #f7f7f7 on the header ROW behind its cells */
  thead,
  tr.mat-mdc-header-row,
  .mdc-data-table__header-row {
    background-color: var(--wu-chrome) !important;
  }
  thead th,
  .mat-mdc-header-cell,
  .mat-header-cell,
  th {
    background-color: var(--wu-chrome) !important;
    color: var(--wu-text) !important;
    border-color: var(--wu-border) !important;
  }
  tbody tr,
  .mat-mdc-row,
  .mat-row {
    background-color: var(--wu-surface) !important;
  }
  /* zebra: WU alternates white / #f7f7f7 */
  tbody tr:nth-child(even),
  .mat-mdc-row:nth-child(even),
  .mat-row:nth-child(even) {
    background-color: var(--wu-surface-2) !important;
  }
  td,
  .mat-mdc-cell,
  .mat-cell {
    color: var(--wu-text-2) !important;
    border-color: var(--wu-border) !important;
  }
  tbody tr:hover,
  .mat-mdc-row:hover {
    background-color: #232a33 !important;
  }
  /* The city page's Nearby Weather Stations table paints its row hover with WU's
     own `#station-list tr:hover { rgba(142,209,233,.5) !important }` -- an id
     selector plus `!important`, so it out-specifies the (0,1,1) rule above and
     the wash survives. Composited over the card that is a ~rgb(85,121,136) steel
     blue: the row's link drops to ~2.0:1 and its muted timestamp to ~2.4:1, so
     the one row you are pointing at is the one you cannot read. Hover-gated, so
     no load-time scan reaches it. Angular compiles WU's rule with its own
     `_ngcontent-*` attribute, putting it at (1,2,2), so the id alone is not
     enough -- the `[id]` attribute is load-bearing, it is what clears that
     column, and the `> td` pair keeps the fill even if a future build adds
     another qualifier to the row. */
  #station-list[id] tbody tr:hover,
  #station-list[id] tbody tr:hover > td {
    background-color: #232a33 !important;
  }
  /* The Nearby Weather Stations table is paged by a Material paginator whose
     range label is `rgba(0,0,0,.87)` from a rule more specific than the
     `.data-module *` colour:inherit above, and whose chevrons are SVGs painted
     through `fill` (not `color`), so no text-colour rule reaches them: the
     "1 - 10 of 33" readout and all four page buttons render near-black on the
     dark card. Material encodes enabled/disabled in that fill alone
     (`rgba(0,0,0,.54)` vs `.12`) -- keep the two apart. Note every button also
     carries `mat-mdc-button-disabled-interactive`, so the state token must be
     matched as a whole class, never as a substring. */
  .mat-mdc-paginator-range-label,
  .mat-mdc-paginator-page-size-label {
    color: var(--wu-text-2) !important;
  }
  .mat-mdc-paginator-icon {
    fill: var(--wu-text-2) !important;
  }
  .mat-mdc-paginator .mat-mdc-button-disabled .mat-mdc-paginator-icon {
    fill: var(--wu-border-2) !important;
  }

  /* ---- forms / search --------------------------------------------------- */
  input,
  textarea,
  select,
  .wu-search,
  .mat-mdc-input-element,
  .mat-input-element {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
    border-color: var(--wu-border-2) !important;
  }
  input::placeholder,
  textarea::placeholder,
  .wu-search::placeholder {
    color: var(--wu-text-muted) !important;
    opacity: 1 !important;
  }

  /* search autocomplete dropdown / mat menus / panels must be opaque */
  .mat-mdc-autocomplete-panel,
  .mat-autocomplete-panel,
  .mat-mdc-menu-panel,
  .mat-menu-panel,
  .mat-mdc-select-panel,
  .mat-select-panel,
  .cdk-overlay-pane,
  .mat-mdc-dialog-surface,
  .mat-dialog-container,
  .typeahead,
  .results,
  .autocomplete,
  .mat-mdc-option,
  .mat-option {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .mat-mdc-option:hover,
  .mat-option:hover,
  .mat-mdc-option.mdc-list-item--selected,
  .mat-option.mat-active {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }

  /* ---- buttons ---------------------------------------------------------- */
  button,
  .mat-mdc-button,
  .mat-button,
  .mdc-button {
    color: var(--wu-text) !important;
  }
  .mat-mdc-raised-button,
  .mat-raised-button,
  .mdc-button--raised,
  .btn {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
    border-color: var(--wu-border-2) !important;
  }

  /* WU's brand CTA buttons use a bright cyan (#19aadb) that gives weak contrast
     with white text on dark. Refine the brand cyan to a deeper blue of the same
     family so the white label reads clearly while staying recognizably WU. */
  .button,
  a.button,
  button.button,
  .submit-button .button,
  .subnav .button,
  a.mat-mdc-menu-trigger.button,
  .button.split,
  .weather-chart-options .button {
    background-color: #1f7fb8 !important;
    color: #ffffff !important;
    border-color: #1f7fb8 !important;
  }
  .button:hover,
  a.button:hover {
    background-color: #2a93cf !important;
    color: #ffffff !important;
  }
  /* Brand CTA buttons INSIDE a .data-module (e.g. health "Buy Your Sensor Now" and
     "Learn more about air pollution") are flattened to a transparent fill by the
     `.data-module *:not(img):not(svg):not(canvas):not(picture):not(.module-header)`
     neutralizer, whose four element :not()s + .module-header put it at (0,2,4) --
     it out-specifies the generic `.button` brand rule, so the cyan fill vanishes and
     the button reads as bare white text with a thin border. Re-assert the brand fill
     with a three-class prelude that clears (0,2,4). */
  .data-module a.button.radius,
  .data-module .content a.button,
  .data-module .content .button,
  .current-container .content a.button,
  .list-container .content a.button {
    background-color: #1f7fb8 !important;
    border-color: #1f7fb8 !important;
    color: #ffffff !important;
  }

  /* ---- footer ----------------------------------------------------------- */
  footer,
  .footer,
  .global-footer {
    background-color: var(--wu-chrome) !important;
    color: var(--wu-text-2) !important;
  }
  footer a,
  .footer a {
    color: var(--wu-text-2) !important;
  }
  footer a:hover {
    color: var(--wu-link-hover) !important;
  }

  /* ---- keep weather imagery / data viz untouched ------------------------ */
  /* radar, satellite, wundermap, leaflet tiles, charts, condition icons,
     temperature swatches and alert banners must render their real pixels --
     do not paint backgrounds onto these. */
  img,
  svg,
  canvas,
  video,
  picture,
  .leaflet-container,
  .leaflet-tile,
  .wundermap,
  #map,
  .map-container,
  .radar,
  .satellite,
  [class*="chart"],
  [class*="graph"],
  highcharts-chart,
  .highcharts-container {
    background-color: transparent !important;
  }
  /* never let the blanket border rule outline map/chart tiles */
  .leaflet-container *,
  .highcharts-container * {
    border-color: transparent !important;
  }

  /* ====================================================================== */
  /* SVG data-viz surfaces a plain DOM-background audit can't see.          */
  /* These are WU's own custom SVG charts (NOT raster radar/maps, NOT       */
  /* canvas, NOT Highcharts) -- so their CHROME is safe to theme while the  */
  /* colored data SERIES are preserved. Raster radar/satellite imagery is   */
  /* never touched (it lives in <img>/leaflet tiles, handled above).        */
  /* ====================================================================== */

  /* ---- (1) current-conditions temperature circle ------------------------ */
  /* .conditions-circle is a border-radius:50% div whose INTERIOR is a white
     ::before disc. Darken the disc to an elevated surface. The RING is a
     linear-gradient WU recomputes from the current temperature (cool blues ->
     warm oranges/reds), so it must be left exactly as authored -- painting a
     fixed red over it destroys the reading. Only the disc is themed. */
  .conditions-circle::before {
    background: var(--wu-surface) !important;
  }
  .conditions-circle .condition-data,
  .conditions-circle .hi-lo,
  .conditions-circle .hi,
  .conditions-circle .lo,
  .conditions-circle .separator,
  .conditions-circle .feels-like,
  .conditions-circle .feels-like-label {
    color: var(--wu-text) !important;
  }
  .conditions-circle .hi-lo .hi {
    color: #ff6b6b !important;          /* warm high */
  }
  .conditions-circle .hi-lo .lo {
    color: #4d9fe6 !important;          /* cold low  */
  }
  /* the big current temperature stays the WU orange accent (semantic). */
  .conditions-circle .temp,
  .conditions-circle .wu-value,
  .conditions-circle .current-temp {
    color: #ff9d4d !important;
  }
  /* the small "Gusts" dial ring -> subtle dark border. */
  .dial {
    border-color: var(--wu-border-2) !important;
  }
  /* Its wind-direction needle is a CSS triangle (border-width: 18px 6px 0)
     whose side borders must stay transparent. The blanket `*` border reset
     paints all four sides, so the needle renders as a solid dark rectangle --
     and dark-on-dark at that. Restore the triangle and light the tip. */
  .dial .arrow-direction {
    border-top-color: var(--wu-text) !important;
    border-right-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: transparent !important;
  }

  /* ---- (2) 10-day multi-panel SVG charts -------------------------------- */
  /* The white plot stripes are <rect class="bc-bar"> day-column bands filled
     #f7f7f7; gridlines/border are #e7e7e7; axis labels + the pressure line
     are near-black (#1e2023) -> invisible on dark. Darken the bands, mute
     the grid, and lift the near-black axis text / data line to light. The
     SATURATED series (temp red, feels-like magenta, dew-point green, cloud
     grey, precip/wind blue, humidity) are left as authored. */
  svg.chart .bc-bar.bar-on,
  svg.chart rect.bc-bar {
    fill: var(--wu-surface-2) !important;
  }
  svg.chart .tick-line,
  svg.chart line.tick-line,
  svg.chart rect.border {
    stroke: var(--wu-border) !important;
  }
  /* axis tick labels (#1e2023) -> readable muted light. */
  svg.chart text,
  svg.chart .tick-label {
    fill: var(--wu-text-muted) !important;
  }
  /* remap ONLY the near-black data line (Pressure, #1e2023) so it stays
     visible; the colored series keep their hues. */
  svg.chart path[stroke="#1e2023"],
  svg.chart path[stroke="rgb(30, 32, 35)"],
  svg.chart .pressure path,
  svg.chart path.pressure {
    stroke: var(--wu-text-2) !important;
  }
  /* Every chart legend swatch (span.legend-key) carries its series colour, but
     Pressure's is the same near-black #1e2023 -- invisible on dark, and no
     longer matching the line we just lifted. Match it to the lifted stroke. */
  .legend-def.pressure .legend-key {
    background-color: var(--wu-text-2) !important;
  }
  /* "Chance of Snow" is the one series whose key is a pink fill INSIDE a 2px
     #15aadc ring (it pairs with the cyan "Chance of Precip."). The blanket `*`
     border reset flattened that ring, so the two related series stopped reading
     as a pair. The fill is untouched. */
  .legend-def.snowchance .legend-key {
    border-color: #15aadc !important;
  }
  /* WU's form checkbox is an <input type=checkbox> + <label> whose visible box
     is the LABEL's ::before painted from wu4Form_sprite.png. UNCHECKED is a
     solid white cell of that sprite -- a bg-IMAGE on a pseudo-element, so
     neither the element-bg scan nor a pseudo-bg-COLOR probe sees it, and every
     instance is click-gated on top of that. Invert only the unchecked cell
     (white box -> near-black with a legible rim); the checked cell is a cyan
     tick that already reads on dark and must keep its hue, so it is exempted
     via :checked. Two instances: the 10-day "Customize" series menu and the
     city-page station-nav "Report Station" dropdown. */
  .wu-forecastextended-seriesselector-preset label::before,
  .checkbox-wrap label::before {
    filter: invert(1) brightness(2.2) !important;
  }
  .wu-forecastextended-seriesselector-preset input:checked + label::before,
  .checkbox-wrap input:checked + label::before {
    filter: none !important;
  }

  /* ---- (3) dashboard tiles (Precip / Pollen / Air Quality / UV) --------- */
  /* Each lib-*-tile body is a div#*BarChart wrapping an inline-styled white
     <svg> whose bars are <rect fill="#e7e7e7">. Darken the body + svg bg and
     the bars; the colored value text + top accent rules are kept by the
     rules above (value colors are semantic). */
  lib-precip-tile a,
  lib-pollen-tile a,
  lib-air-quality-tile a,
  lib-uv-tile a,
  lib-precip-tile [id$="BarChart"],
  lib-pollen-tile [id$="BarChart"],
  lib-air-quality-tile [id$="BarChart"],
  lib-uv-tile [id$="BarChart"],
  #precipBarChart,
  #pollenBarChart,
  #airQualityBarChart,
  #uvBarChart,
  #aqiBarChart {
    background-color: var(--wu-surface) !important;
  }
  lib-precip-tile svg,
  lib-pollen-tile svg,
  lib-air-quality-tile svg,
  lib-uv-tile svg {
    background-color: var(--wu-surface) !important;
  }
  /* The chevron ("more") column on the right of each tile is a 20px #f7f7f7
     strip (.hook-arrow) holding the blue ">" link icon -> a bright white bar.
     Darken it to the tile surface; the blue arrow still reads. */
  lib-precip-tile .hook-arrow,
  lib-pollen-tile .hook-arrow,
  lib-air-quality-tile .hook-arrow,
  lib-uv-tile .hook-arrow,
  .hook-arrow {
    background-color: var(--wu-surface) !important;
  }
  /* the light-grey mini bars -> a soft elevated tone that reads on dark. */
  lib-precip-tile svg rect,
  lib-pollen-tile svg rect,
  lib-air-quality-tile svg rect,
  lib-uv-tile svg rect {
    fill: #3a424d !important;
  }
  /* The tiles' <text> nodes are inline-styled. The VALUE lines carry saturated
     semantic fills (precip cyan, pollen orange, AQI amber, UV red) and must be
     kept; only the descriptive caption ("Slight rain chance...", "Grass Pollen")
     is WU's neutral #4c4c4c, which drops to ~1.4:1 on the dark tile. `fill` is
     not `color`, so every text-colour audit reads it as clean -- match the
     inline fill directly and lift just that one. */
  text[style*="fill: rgb(76, 76, 76)"] {
    fill: var(--wu-text-muted) !important;
  }
  /* The AQ "Air Quality Index" and UV "Daytime UV" caption <text> nodes carry NO
     inline fill, so they inherit the SVG default black (#000) and vanish on the
     dark tile -- the #4c4c4c catch above only matches captions styled that hue.
     Lift every tile caption that has no inline fill; the value <text> keeps its
     inline semantic fill (purple/red/cyan/orange), which this :not() excludes. */
  lib-precip-tile text:not([style*="fill"]),
  lib-pollen-tile text:not([style*="fill"]),
  lib-air-quality-tile text:not([style*="fill"]),
  lib-uv-tile text:not([style*="fill"]) {
    fill: var(--wu-text-muted) !important;
  }

  /* ====================================================================== */
  /* Page-type fixes found in deep review (calendar, hourly, news,          */
  /* wundermap, search dropdown, sponsored widget, global controls).        */
  /* ====================================================================== */

  /* ---- calendar grid ---------------------------------------------------- */
  /* WU paints in-month day cells white (#fff) and other-month cells light
     grey (#d7d7d7). The cell TEXT is already lifted to light by the rules
     above, so on a white cell it reads light-on-white (invisible). Darken the
     cells: in-month -> surface, out-of-month -> dimmer elevated. */
  .calendar-day,
  li.calendar-day {
    background-color: var(--wu-surface-2) !important;
  }
  .calendar-day.current-month {
    background-color: var(--wu-surface) !important;
  }
  /* weekday column headers (Sunday..Saturday) are #1e2023 -> readable. */
  .calendar-weekday,
  .calendar-weekday .desktop,
  .calendar-weekday .mobile {
    color: var(--wu-text-2) !important;
  }
  /* the day high-temp keeps WU's deep red (#d5202a), too dark on a dark cell;
     lift to the same warm red the rest of the theme uses (low stays cyan). */
  .calendar-day .temperature .hi,
  .calendar-day span.hi {
    color: #ff6b6b !important;
  }

  /* ---- hourly "next day" expander bar ----------------------------------- */
  /* #nextForecasts is a full-width #f7f7f7 "NEXT DAY HOURLY FORECAST" button
     bar with near-invisible text once the page is dark. */
  #nextForecasts {
    background-color: var(--wu-surface-2) !important;
  }
  /* its label is WU blue (#006f9e) -- it is the module's only CTA, so keep the
     link colour rather than greying it into plain text. */
  #nextForecasts,
  #nextForecasts * {
    color: var(--wu-link) !important;
  }

  /* ---- news & blogs cards ----------------------------------------------- */
  /* Alternating article rows (#f7f7f7) and the recent-infographics modules
     (#fff) keep a light background, so the lifted light text vanishes on them.
     Darken the card surfaces; the article images are untouched. */
  .news-item,
  .news-list .news-item,
  lib-article-list .news-item,
  lib-infographic-recent-list .basic-module,
  lib-infographic-recent-list .stack,
  .basic-module .content .stack,
  .infographic-item,
  .poster-item,
  lib-cat-six-article,
  lib-cat-six-article .cat-six-article,
  .cat-six-article,
  lib-cat-six-about-author,
  lib-cat-six-about-author .cat-six-about-author,
  .cat-six-about-author {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }

  /* Every teaser card is wrapped in a single <a>, so WU's two roles land on the
     wrong elements and swap: the HEADLINE is the site's #006f9e link but our
     `h1..h6` lift repaints it plain white, while the summary PARAGRAPH is WU's
     #1e2023 body copy but inherits the anchor's link blue. The card still reads
     legibly, so no contrast or background audit sees it -- what is gone is the
     cue for which line you are clicking. Put both roles back. */
  .news-item .title,
  .news-item h3.title {
    color: var(--wu-link) !important;
  }
  .news-item a:hover .title {
    color: var(--wu-link-hover) !important;
  }
  .news-item p {
    color: var(--wu-text-2) !important;
  }

  /* The Infographics index builds its grid from `.cta-module` cards, a class
     none of the news/blog selectors above reach: they keep WU's #f7f7f7 panel,
     so the lifted white title lands white-on-white. Its heading and paragraph
     carry the same swapped pair as `.news-item` above. */
  .cta-module {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .cta-module h3 {
    color: var(--wu-link) !important;
  }
  .cta-module a:hover h3 {
    color: var(--wu-link-hover) !important;
  }
  .cta-module p {
    color: var(--wu-text-2) !important;
  }

  /* The Category 6 blog separates its sections with <span class="cat-six-line">, a
     2px #bdbdbd rule painted as a background-COLOR rather than a border, so the
     blanket `*` border reset never touches it and it is far below the light-surface
     scan's size floor -- it renders as a bright grey bar straight across the dark
     page. Mute it to the component line colour. */
  .cat-six-line {
    background-color: var(--wu-border-2) !important;
  }

  /* The Category 6 blog "ALL SECTIONS" filter is a Material <mat-select> whose
     trigger renders as a #f7f7f7 box with near-black value/arrow -- a glaring
     white pill on the dark page. Darken the trigger and lift its value + arrow;
     the open panel is already handled by the .mat-mdc-select-panel rule above. */
  mat-select,
  .mat-mdc-select,
  .mat-mdc-select-trigger,
  .cat-six-grid mat-select {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* WU paints a light dropdown-arrow chip on the right of the <mat-select> via a
     sprite background-IMAGE (sprite-common-vert.png) -- a white rounded button
     that survives the bg-color darkening (audit-blind). Drop it; the Material
     grey triangle arrow (.mat-mdc-select-arrow) still indicates the control. */
  mat-select.mat-mdc-select,
  .cat-six-dropdown mat-select {
    background-image: none !important;
  }
  .mat-mdc-select-value,
  .mat-select-value,
  .mat-mdc-select-value-text,
  .mat-mdc-select-min-line {
    color: var(--wu-text) !important;
  }
  .mat-mdc-select-arrow,
  .mat-select-arrow,
  .mat-mdc-select-arrow svg {
    color: var(--wu-text-muted) !important;
    fill: var(--wu-text-muted) !important;
  }

  /* Article-detail "Recent Stories" rail: lib-recent-stories wraps a
     .recent-stories.basic-module whose inner .content body is a #f7f7f7 white
     panel (header/footer already dark) -> the whole rail reads white. Darken
     the module + its content body; thumbnails and blue titles stay intact. */
  lib-recent-stories,
  lib-recent-stories .recent-stories,
  lib-recent-stories .basic-module,
  lib-recent-stories .content,
  .recent-stories.basic-module,
  .recent-stories .content {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }

  /* The video-promo / top-stories carousel pager is a row of .dot discs whose
     ONLY styling is a background-color (#a3a3a3 idle, #19aadb current). The
     blanket `.data-module *` transparent-neutralizer above zeroes both, so the
     pager renders as empty space between the arrows -- there is no indication
     of how many slides exist or which one is showing. */
  .data-module .navigation .dot {
    background-color: #6a737d !important;
  }
  .data-module .navigation .dot.active {
    background-color: #19aadb !important;
  }

  /* The "brand-new Weather Underground" promo ribbon is a solid #19aadb band
     with a white inline link. Our generic `a` rule repaints it the dark-page
     link blue -> 1.7:1 on the cyan. Restore white inside the ribbon. */
  .infoBox a,
  .msgWrapper a {
    color: #ffffff !important;
  }
  /* WU rims that band with a 2px #008fbf, a darker shade of its own cyan, so it
     reads as one solid chip. The blanket `*` reset repaints it the theme line
     colour, which on the dark page draws a hard dark box around the ribbon. */
  .infoBox,
  .msgWrapper {
    border-color: #008fbf !important;
  }

  /* Severe-weather alert banner (.DF1 red / .DF2 orange / .DF3 amber / .DF4-5
     grey) keeps its saturated severity background; WU paints ALL its text --
     including the inline alert link (.alert-inner a) -- white on that band. Our
     generic `a` lift repaints the "Heat Advisory (See More)" link the dark-page
     link blue, which drops to ~1.9:1 on the amber/orange banners. Restore white. */
  .alert-inner a,
  .alert-wrapper .alert-inner a {
    color: #ffffff !important;
  }
  /* WU draws the band's 1px border in the SAME severity colour as its fill, so
     natively it is invisible; the blanket `*` reset turns it into a dark
     hairline boxing in the alert. Transparent shows the fill through the
     border box, which is exactly what WU renders -- and it needs no per-level
     hex, so DF4/DF5 stay correct too. */
  .DF1,
  .DF2,
  .DF3,
  .DF4,
  .DF5 {
    border-color: transparent !important;
  }

  /* ---- wundermap page --------------------------------------------------- */
  /* #inner-wrap is a white page wrapper (flashes white while leaflet tiles
     load); the top ad slot (#top-banner-ad-browser) is a light-grey band; the
     layer-panel accordion bodies (.accordion-content) are white. Map tiles,
     markers and overlays are untouched (img/canvas/leaflet handled above). */
  #inner-wrap {
    background-color: var(--wu-base) !important;
  }
  #top-banner-ad-browser,
  #position-1-banner-ad-browser {
    background-color: var(--wu-chrome) !important;
  }
  /* The radar-animation transport strip (rewind / prev / play / next / end, the
     scrubber wrapper and the speed dropdown) is a row of `.control-button` chips
     WU paints rgba(247,247,247,.98) with a dim teal (#006f9e) glyph. Our generic
     form rules DO reach inside it -- the "1x" <select> and the scrubber <input>
     both compute dark -- so the strip shipped as dark pills sitting in a white
     pad floating over the map. Each chip is 31x31, under the light-surface scan's
     size floor, so only a screenshot shows it. Darken the strip to the same
     surface as the controls it holds and keep WU's cyan chip divider. Scoped to
     `.control-button`: the city-page radar card's play button carries only
     `.mapPlay` and stays native map chrome. */
  .control-button,
  .control-button.control-scrubber,
  .control-button.control-dropdown {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-link) !important;
    border-right-color: #15aadc !important;
  }

  wm-layer .accordion-content,
  wxstn-layer .accordion-content,
  .layers-container .accordion-content,
  .accordion-content {
    background-color: var(--wu-surface) !important;
  }
  /* The redesigned layers/legend flyout no longer uses .accordion-content: its
     body is now <ul.map-accordion> (WU's native #3d3d3d medium grey) inside
     wm-layers/wm-legend, and each group header is a <span.section> band painted
     WU's #696969 -- neither reached by the .accordion-content rule above, so the
     whole panel shipped in native greys, lighter than the dark theme. Darken the
     body to a card surface and the header bands to the elevated tone; the row
     labels are already lifted to light text by the rules above. */
  .map-accordion,
  .menu-content .item-content,
  wm-layers,
  wm-legend {
    background-color: var(--wu-surface) !important;
  }
  .map-accordion .section,
  .menu-content .section {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* Every ROW of that panel is a <label.layerTitle> carrying its own WU grey
     (#3d3d3d top level, #2f2f2f for the nested layer-type options) -- so the
     rules above darkened the container while all the rows stayed mid-grey and
     the whole flyout read washed-out against the theme. Neither scan sees it:
     the greys are neither near-white nor chromatic. Keep WU's two-level
     hierarchy (nested rows darker than their parent). The rail itself
     (lib-wm-sidebar) and its in-panel ad box (#696969) are the same grey. */
  .map-accordion .layerTitle,
  .menu-content .layerTitle {
    background-color: var(--wu-surface) !important;
  }
  .accordion-content .layerTitle {
    background-color: var(--wu-surface-2) !important;
  }
  /* Every layer toggle in that panel is a <span.wuCheckbox>/<span.wuRadioButton>
     whose art is a background-IMAGE sprite (wu4Checkbox.png / wu4RadioButton.png).
     The UNCHECKED cell is a solid white box/disc -- 16 checkboxes and 3 radios of
     glaring white on the darkened panel, at 24x24 each (under the light-surface
     size floor) and painted by a bg-image, so no bg-colour scan reports them.
     Invert the unchecked art; the checked/selected cells are WU's cyan tick and
     cyan-ringed dot, which read correctly on dark and are exempted so the
     on/off distinction survives. State is encoded by background-position, so
     the exemption must key off `.selected` (WU's own class), not the sprite.
     `.map-accordion` scopes this to both the desktop rail and the
     .mobile-wundermap-wrapper copy. */
  .map-accordion .wuCheckbox,
  .map-accordion .wuRadioButton {
    filter: invert(1) brightness(2.2) !important;
  }
  .map-accordion .selected .wuCheckbox,
  .map-accordion .wuRadioButton.selected {
    filter: none !important;
  }
  lib-wm-sidebar {
    background-color: var(--wu-chrome) !important;
  }
  .pane-wu-fullscreenweather-ad-box-atf {
    background-color: var(--wu-chrome) !important;
  }
  /* The rail's flyout wrapper (.tab-content.legend in .sidebar-tab-container) is a
     #f7f7f7 panel. The Layers pane (wm-layers) is opaque dark and covers it, but the
     Legend pane (wxstn-legend/.legends_panel) is transparent, so the white leaks
     through with the theme's light .legendTitle text on it (invisible). Click-gated,
     so no load-time scan reaches it. Darken the wrapper. */
  .sidebar-tab-container .tab-content,
  .tab-content.legend {
    background-color: var(--wu-surface) !important;
  }
  /* The legend graphic (.legendImage.gkey) is a raster PNG scale/key -- the map's
     temperature/wind/precip colour code, baked with dark labels for a light bg. It is
     data-viz we must keep legible, not recolour, so give it a light pad rather than
     darkening it dark-on-dark. */
  .legendImage.gkey {
    background-color: #f7f7f7 !important;
  }
  /* The Layers/Save Pref/Share/Settings/Legend rail gives EACH tab its own
     identity colour as a 3px left border, keyed by :nth-child (red, orange,
     amber, green, cyan -- WU's own hexes). The blanket `*` border reset flattens
     all five to the line colour; the previous fix restored only `li.active` as
     red, which merely happened to match tab 1 (Layers) and left the other four
     grey. Restore the whole scale on both the desktop rail and the mobile one.
     Their #696969 bottom separator stays muted (handled by the `*` reset). */
  .sidebar-tab-container .items-list li:nth-child(1),
  .mobile-wundermap-wrapper .items-list li:nth-child(1) {
    border-left-color: #d5202a !important;
  }
  .sidebar-tab-container .items-list li:nth-child(2),
  .mobile-wundermap-wrapper .items-list li:nth-child(2) {
    border-left-color: #ff8833 !important;
  }
  .sidebar-tab-container .items-list li:nth-child(3),
  .mobile-wundermap-wrapper .items-list li:nth-child(3) {
    border-left-color: #ffb92f !important;
  }
  .sidebar-tab-container .items-list li:nth-child(4),
  .mobile-wundermap-wrapper .items-list li:nth-child(4) {
    border-left-color: #5b9f49 !important;
  }
  .sidebar-tab-container .items-list li:nth-child(5),
  .mobile-wundermap-wrapper .items-list li:nth-child(5) {
    border-left-color: #15aadc !important;
  }
  /* WU marks the open pane by lifting that tab one step above the rail
     (#4c4c4c on its native #3d3d3d). We darkened the rail to the chrome tone
     and left the lift at #4c4c4c, so the subtle native step became a mid-grey
     slab on near-black. Neither scan sees it: it is dark-on-dark and
     achromatic. Re-state the step in the theme's own elevation. */
  .sidebar-tab-container .items-list li.active,
  .mobile-wundermap-wrapper .items-list li.active {
    background-color: var(--wu-surface) !important;
  }
  /* Below the desktop breakpoint the whole rail collapses into
     `.mobile-wundermap-wrapper`, a component none of the desktop wundermap
     selectors above reach. Two separate faults, both mobile-only:

     (a) its collapsed header `.menu-title` is a #f7f7f7 bar floating over the
         map -- a full-width white slab. Its label, the "..." `::before` and the
         open/close caret `::after` (a CSS triangle whose colour lives in
         border-color, so the blanket `*` reset never touched it) are all WU's
         dim teal #006f9e, ~2.9:1 once the bar is dark. */
  .mobile-wundermap-wrapper .menu-title {
    background: var(--wu-surface) !important;
    color: var(--wu-link) !important;
  }
  .mobile-wundermap-wrapper .menu-title::before {
    color: var(--wu-link) !important;
  }
  .mobile-wundermap-wrapper .menu-title::after {
    border-top-color: var(--wu-link) !important;
    border-bottom-color: var(--wu-link) !important;
  }
  /* (b) every layer row in the open panel keeps the near-black text WU wrote for
         its light mobile panel (`.layerTitle` #1e2023, `.selected` #4c4c4c) --
         and its inner .layerName / .opacity-title / .slideroutput inherit it. We
         darkened the panel and never lifted them, so "Weather Stations",
         "Temperature / Wind" and every checkbox label render at ~1.1:1: the
         panel looks like a column of unlabelled checkboxes. The DESKTOP panel is
         natively light (#fff/#ddd), so this stays scoped to the mobile wrapper. */
  .mobile-wundermap-wrapper .layerTitle,
  .mobile-wundermap-wrapper .layerName,
  .mobile-wundermap-wrapper .opacity-title,
  .mobile-wundermap-wrapper .slideroutput,
  .mobile-wundermap-wrapper .layerTitle input {
    color: var(--wu-text-2) !important;
  }
  .mobile-wundermap-wrapper .layerTitle.selected,
  .mobile-wundermap-wrapper .layerTitle.selected .layerName {
    color: var(--wu-text) !important;
  }
  /* (c) the panel caps itself with a `.done-wrapper` footer holding the "Done"
         button, painted #fff -- a white slab under the otherwise-dark layer list.
         It only has a box on the MOBILE wundermap (the desktop Save-Pref copy
         computes 0x0), it sits below the panel's scroll fold, and the panel is
         click-gated, so nothing but opening it and scrolling down shows it. */
  .done-wrapper,
  .menu-content .item-content .done-wrapper {
    background-color: var(--wu-surface) !important;
  }

  /* ---- station selector ("CHANGE" next to the city name) ---------------- */
  /* Click-gated, so no load-time scan sees it. Each row paints #fff on THREE
     separate cells (.icon-wrapper, the row anchor, .temp) rather than on the
     row, so darkening the panel leaves white strips behind every station. The
     .temp cell is worse: our light-value lift left white-on-white numbers. */
  /* WU paints the cells with its own `!important` at (1,4,0) specificity, so
     the second id is load-bearing: it is what lets us win the cascade. */
  #stationselector_list,
  #stationselector_table {
    background-color: var(--wu-surface) !important;
  }
  /* The widget's OUTER container (#stationselector) is a #f7f7f7 white panel; the
     rules above only darken the inner _list/_table, so the container leaked white
     along the widget's top/bottom edges, in the gaps between the three sub-panels,
     AND behind the entire (fully transparent) Current Station card -- its blue title
     read on white and the muted Location/Elevation labels washed out. Darken the
     container to base, and give the Current Station card the same surface as the
     Nearby list so the two side panels match. */
  #stationselector {
    background-color: var(--wu-base) !important;
  }
  #stationselector_current {
    background-color: var(--wu-surface) !important;
  }
  #stationselector_list #stationselector_table .table-row > * {
    background-color: var(--wu-surface) !important;
  }
  #stationselector_list #stationselector_table .table-row:hover > * {
    background-color: var(--wu-surface-2) !important;
  }
  /* The Nearby-Stations list caps its scroll area with a bottom fade overlay
     (.scroll-fade in #stationselector_list_footer) painted as a
     linear-gradient to solid #fff -- a glaring white band over the last rows on
     the dark list. It is a background-IMAGE (so the bg-colour audits miss it) AND
     the widget is click-gated (so no load-time scan sees it). Fade to the list
     surface instead so the scroll cue reads as a soft dark vignette. */
  #stationselector .scroll-fade,
  #stationselector_list_footer .scroll-fade,
  .scroll-fade {
    background: linear-gradient(rgba(28, 33, 40, 0), var(--wu-surface)) !important;
  }

  /* ---- search autocomplete (jQuery UI, not Material) -------------------- */
  /* The location search dropdown is a jQuery UI .ui-autocomplete / .ui-menu
     with a white background -- not covered by the Material panel rules above.
     Make the floating surface opaque dark; style hover + the group headers. */
  .ui-autocomplete,
  ul.ui-autocomplete,
  .ui-autocomplete.ui-menu {
    background-color: var(--wu-surface) !important;
    border-color: var(--wu-border-2) !important;
  }
  .ui-autocomplete .ui-menu-item,
  .ui-autocomplete .ui-menu-item-wrapper,
  .ui-autocomplete li {
    background-color: transparent !important;
    color: var(--wu-text-2) !important;
  }
  .ui-autocomplete .ui-menu-item-wrapper.ui-state-active,
  .ui-autocomplete .ui-state-focus,
  .ui-autocomplete .ui-state-active,
  .ui-autocomplete li:hover {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* WU paints the hover fill on the ROW ANCHOR, not the <li>: `.ui-autocomplete
     a:hover / .mimic-a:hover / a.ui-state-hover / a.ui-state-focus` all set
     #f7f7f7. Darkening the li leaves that white strip on top of it, so the
     result-row you are pointing at is a white band carrying our light link text
     (~1.5:1) -- the one row you cannot read. Hover-gated, so no load-time scan
     reaches it. The same anchors back the favourites-list/-mobile panels, which
     share WU's rule; cover the whole family. */
  .ui-autocomplete li:hover > a,
  .ui-autocomplete li:hover > .mimic-a,
  .ui-autocomplete a:hover,
  .ui-autocomplete .mimic-a:hover,
  .ui-autocomplete a.ui-state-hover,
  .ui-autocomplete a.ui-state-focus,
  .ui-autocomplete .mimic-a.ui-state-hover,
  .ui-autocomplete .mimic-a.ui-state-focus,
  .favorites-list ul a:hover,
  .favorites-list ul .mimic-a:hover,
  .favorites-mobile ul a:hover,
  .favorites-mobile ul .mimic-a:hover {
    background-color: var(--wu-surface-2) !important;
  }
  .ui-autocomplete .ui-autocomplete-category {
    color: var(--wu-text-muted) !important;
    background-color: var(--wu-chrome) !important;
  }
  /* The location links inside each result use WU's dim teal (#006f9e), which
     drops to ~2.9:1 on the dark dropdown (fails WCAG). The inner <span> /
     matched .ui-autocomplete-term carry that color, so the generic `a` lift
     doesn't reach them -- brighten them to the dark-friendly link blue. */
  .ui-autocomplete a,
  .ui-autocomplete a span,
  .ui-autocomplete .ui-menu-item-wrapper span,
  .ui-autocomplete .ui-autocomplete-term {
    color: var(--wu-link) !important;
  }
  .ui-autocomplete li:hover a,
  .ui-autocomplete li:hover a span,
  .ui-autocomplete .ui-state-active span {
    color: var(--wu-link-hover) !important;
  }
  /* The search-clear "X" icon is the same dim teal (#006f9e) -> brighten. */
  .close-search i.material-icons,
  #wuSearch-contain .close-search i {
    color: var(--wu-link) !important;
  }

  /* ---- selected sub-nav tab indicator ----------------------------------- */
  /* The active TODAY/HOURLY/... tab paints a 2px white ::after underline. */
  .subnav a.selected::after,
  .subnav-left a.selected::after,
  .subnav-right a.selected::after {
    background-color: var(--wu-link) !important;
  }

  /* ---- mobile sub-navigation tab bar ------------------------------------ */
  /* Below the desktop breakpoint WU swaps the .subnav for a scrolling
     ul#subnav-mobile whose bar, every li AND every anchor each carry their own
     #f7f7f7. None of the .subnav selectors reach it, so the tab bar shipped as
     a full-width white strip -- invisible to a desktop-only review. */
  #subnav-mobile,
  #subnav-mobile li,
  #subnav-mobile li > a {
    background-color: var(--wu-base) !important;
  }
  #subnav-mobile li.selected,
  #subnav-mobile li.selected > a {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* On mobile the "you are here" marker is a 3px TOP border on the selected
     anchor (`.tab-layout .subnav-mobile a.selected { border-top-color }`), the
     counterpart of the desktop tab's coloured `::after` bar. The blanket `*`
     reset flattens it to the generic line colour, so the bar goes dead. Match
     the accent the desktop underline already uses. */
  #subnav-mobile li.selected > a.selected,
  #subnav-mobile a.selected {
    border-top-color: var(--wu-link) !important;
  }
  /* the overflow scroll chevrons that cap the bar are their own #fff chips */
  .subnav-arrow,
  .subnav-arrow-left,
  .subnav-arrow-right {
    background-color: var(--wu-base) !important;
  }

  /* ---- global header geolocate icon ------------------------------------- */
  /* The "use my location" gps icon is WU blue (#006f9e) -> too dim on dark. */
  .geolocate-wrap i.material-icons,
  .geolocate-wrap .material-icons,
  #wuSearch-contain .geolocate-wrap i {
    color: var(--wu-link) !important;
  }

  /* ---- header settings / units quick dropdown --------------------------- */
  /* The gear icon opens a Foundation .dropdown-pane (#wuSettings-quick) that
     WU paints #fff -- a glaring white units panel on the dark page. It is
     click-gated, so no load-time scan sees it. Darken the pane to a card
     surface; the °F/°C toggle (WU blue) and the "More Settings" link already
     read on it. */
  #wuSettings-quick,
  .wu-settings-quick,
  .dropdown-pane {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  /* The °F/°C segmented toggle marks the ACTIVE unit with nothing but a 3px
     border, and WU ships it in THREE places that each need the same treatment:
     the header gear pane and the wundermap Settings pane (both `.button-group`,
     #bdbdbd on the selected half and #ffffff on the other) and the mobile
     sidenav's `.button-group-dark`, where selected is a recessed #333 with a
     #19aadb label and unselected a raised #696969 with a white one. The blanket
     `*` reset flattens every one of those borders to a single line colour and
     the generic `.button` brand rule then fills BOTH halves the same cyan, so
     none of the three panes showed which unit was in use -- on the mobile one
     the only surviving cue was a cyan focus ring on a cyan button. On the
     wundermap WU also keeps a white fill on both halves with its own
     `!important`, so the `.button` white label rule left the °F/°C glyphs
     invisible on white. All three are click-gated: no load-time scan sees any of
     them. Give the toggle one explicit dark/selected pair everywhere. */
  #wuSettings-quick .button-group .button,
  .button-group.unit_settings .button,
  .button-group-dark .button {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
    border-color: var(--wu-border-2) !important;
  }
  #wuSettings-quick .button-group .button.selected,
  .button-group.unit_settings .button.selected,
  .button-group-dark .button.selected,
  .button-group-dark .button.active {
    background-color: #15aadc !important;
    color: #ffffff !important;
    border-color: #15aadc !important;
  }

  /* The sticky bottom ad-adhesion rail (CafeMedia `.ci-adhesion`, present on
     EVERY page type) is a full-width 1280x100 fixed bar painted
     rgba(255,255,255,.5). It centres a narrower creative inside itself, so the
     translucent white flanks the ad and washes a bright band across the bottom
     of the dark page. It ships `visibility:hidden` until an ad is served, so no
     scan of an ad-free load reports it -- only its computed paint does. Clear
     the wash; the creative itself is untouched. */
  .ci-adhesion {
    background-color: transparent !important;
  }

  /* ---- sponsored "You May Like" widget (Taboola) ------------------------ */
  /* The recommendation widget's ink is chosen per placement, not per site: the
     city-page unit ships item titles at pure #000 (dark-on-dark, invisible)
     while the /news unit ships them in its own #1690bd. Pin the whole family to
     the theme's body ink so no placement can serve an unreadable title; ad
     thumbnails/creatives are untouched (they are <img> / advertiser markup). */
  div[id^="trc_"] .video-title,
  div[id^="trc_"] .video-label,
  .videoCube .video-title,
  .videoCube .video-label,
  .trc-main-label,
  .trc_related_container .video-title {
    color: var(--wu-text-2) !important;
  }
  /* Dismissing a recommendation opens Taboola's feedback flow: a full-cover
     white wash over the card (.trc_exclude_overlay) plus a white popover of
     reasons whose ink Taboola pins on the CHILDREN, so a colour set on the
     panel alone never reaches it. Both ship `visibility:hidden` and are two
     interactions deep (hover the card, click its "x"), so no scan sees them.
     The caret the eye reads is a pseudo-element border, which the blanket
     border reset cannot reach either. */
  .trc_exclude_overlay,
  .trc_popover,
  .trc_popover_title_wrapper,
  .trc_popover_content_wrapper,
  .popupContentWrapper {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .trc_popover_title_wrapper,
  .trc_popover_content_wrapper span,
  .trc_popover_content_wrapper div,
  .trc_popover_content_wrapper label,
  .popupContentWrapper span,
  .popupContentWrapper div,
  .popupContentWrapper label {
    color: var(--wu-text-2) !important;
  }
  .trc_popover_arrow::after,
  .trc_popover_arrow::before {
    border-bottom-color: var(--wu-surface) !important;
    border-top-color: var(--wu-surface) !important;
  }

  .trc_rbox_header_span,
  .trc_desktop_attribution_link span,
  .trc_desktop_disclosure_link span,
  .trc_mobile_attribution_link span,
  .trc_mobile_disclosure_link span,
  .videoCube .branding,
  .videoCube .video-label-source {
    color: var(--wu-text-muted) !important;
  }

  /* ---- PWS / Sensor Network station dashboard --------------------------- */
  /* The /dashboard/pws/<ID> station pages use a SEPARATE component tree from
     the city weather pages: app-dashboard-header (.dashboard__header is a
     full-width #f7f7f7 band) and lib-tile-* modules whose bodies
     (.dashboard__module__content / .module__container) are #f7f7f7 with
     #e7e7e7 (.module__header) header strips. None of the city-page selectors
     reach these, so the whole dashboard shipped white. Theme the chrome +
     surfaces; the embedded map tiles/charts stay intact (handled above). */
  app-dashboard-header,
  .dashboard__header,
  .dashboard__header .row,
  .dashboard__header .columns {
    background-color: var(--wu-base) !important;
    color: var(--wu-text) !important;
  }
  .dashboard,
  .dashboard__module,
  .dashboard__module__content,
  .module__container,
  .module__content,
  .module__body,
  lib-tile-current-conditions,
  lib-tile-map,
  lib-tile-temperature,
  lib-tile-wind,
  lib-tile-pressure,
  lib-tile-precipitation,
  lib-tile-uv,
  lib-tile-humidity,
  lib-tile-dewpoint,
  lib-tile-solar-radiation {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .module__header,
  .dashboard__module__header {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* The new-WU promo ribbon (#19aadb cyan) is fine; just keep its link bright. */
  .dashboard__header a {
    color: var(--wu-link) !important;
  }
  /* The station-history "Previous"/"Next" pager labels are #1e2023 -> invisible
     on dark. Lift to muted. */
  .arrow-label {
    color: var(--wu-text-muted) !important;
  }
  /* The active Graph/Table history tab paints its inner <a> on a white pill.
     Darken to an elevated surface; the blue label still reads. */
  .history-tab-btn.active a,
  .history-tab-btn.active,
  li.tab-item.active a {
    background-color: var(--wu-surface-2) !important;
  }

  /* The station-history date picker uses native <select class="wu-select"> with
     appearance:none and a sprite background-IMAGE (sprite-common-vert.png) that
     paints a WHITE rounded dropdown-arrow chip on the right of every field --
     audit-blind (the select's bg-color is already dark, the sprite survives) so
     four glaring white chips ship on the dark dashboard. Replacing the sprite with
     `none` leaves the four fields with NO dropdown indicator at all: with
     appearance:none there is no UA arrow and a <select> cannot carry a pseudo-
     element, so the only way back is another background-image. Draw the caret as a
     tiny inline SVG in the muted grey the site's other carets use. */
  .wu-select {
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6'%3E%3Cpath fill='%238b949e' d='M0 0h10L5 6z'/%3E%3C/svg%3E") !important;
    background-repeat: no-repeat !important;
    background-position: 94% 50% !important;
  }
  /* The "Previous"/"Next" history pager buttons (.custom-button) use a gradient
     background-IMAGE: enabled = WU cyan (kept), but the DISABLED state (parent
     .nav-button.disabled) paints a light-grey linear-gradient (#c1c1c1->#dbdbdb)
     over its cyan bg-color -> a bright white-grey button on dark (audit reads the
     cyan bg-color, misses the grey gradient). Darken the disabled pager to an
     elevated surface; its chevron icon still indicates the control. */
  .nav-button.disabled .custom-button {
    background: var(--wu-surface-2) !important;
  }

  /* ---- PWS dashboard gauge discs (audit-blind) -------------------------- */
  /* (a) PRESSURE dial: .pressure-dial paints the barometer face as a WHITE
     raster background-IMAGE (url(), not a bg-color or gradient) with black
     ticks/numbers. The bg audit (color only) and the gradient/lightBgImages
     check both miss a url() image. Invert the face: white -> dark, black
     ticks/numbers -> light, so the gauge reads on dark with no recolor needed. */
  .pressure-dial {
    filter: invert(1) !important;
  }
  /* Every PWS gauge NEEDLE is a separate <img> SVG that is a SIBLING of the dial
     it points at, never a child, so the dial's own filter can never reach it --
     and each one is a single solid shape drawn for a white page:
     Pressure-Dial-Marker.svg is `fill="#000000"` (invisible once the barometer
     face is inverted to near-black: the dial shipped with NO needle at all, the
     whole reading gone) and Wind-Marker.svg is `fill="#4A4A4A"` (~1.8:1 on the
     tile -- the wind-direction wedge reads as a smudge). Inverting each marker
     turns them light without touching the shape or the rotation the wrapper
     applies. Both are raster <img>, so no fill/stroke override can reach them
     and no DOM scan can see them. */
  .pressure-dial__container .pressure-marker,
  img.pressure-marker,
  .wind-dial__container .arrow-wrapper img {
    filter: invert(1) !important;
  }
  /* (b) SOLAR RADIATION gauge: an inline <svg> whose outer disc is
     <circle fill="#EDEDED"> (the audit's white-fill scan only recognizes
     #fff/white literals, so a light hex like #EDEDED slips past) with an
     orange <circle fill="#FF9A3B"> sun on top. Darken only the light track
     disc; the orange intensity indicator is semantic and kept. */
  lib-tile-solar-radiation circle[fill="#EDEDED"],
  lib-tile-solar-radiation circle[fill="#ededed"],
  .dashboard__module circle[fill="#EDEDED"],
  .dashboard__module circle[fill="#ededed"] {
    fill: var(--wu-surface-2) !important;
    stroke: var(--wu-border-2) !important;   /* mute its #E7E7E7 track ring */
  }
  /* (c) UV INDEX gauge: an inline <svg> pyramid whose empty (unreached) level
     segments are <polygon fill="#EDEDED"> -- the same light hex as the solar
     disc, so it is audit-blind for the same reason and shipped as a glaring
     white triangle on the dark tile. Darken ONLY the #EDEDED empty segments;
     the reached-level segments carry their semantic green/yellow/orange/red
     fills and are preserved. */
  lib-tile-uv polygon[fill="#EDEDED"],
  lib-tile-uv polygon[fill="#ededed"],
  .dashboard__module polygon[fill="#EDEDED"],
  .dashboard__module polygon[fill="#ededed"] {
    fill: var(--wu-surface-2) !important;
  }

  /* ---- health / air-quality, pollen, UV, flu & feels-like page ---------- */
  /* The /health page stacks several modules (#pollen_section, #uv_section,
     .flu-activity, .feels-like / .wind-chill-heat, the AQ .monitors table)
     that share their own class-driven near-black text no city-page rule
     reaches. On dark they shipped invisible: the current-level
     .status.label-xlarge values and .flu-activity .label (#1e2023) vanished
     entirely, the Trees/Grass/Weed .tab-nav labels (#333) were near-invisible,
     and the small metadata/legend/table-header labels (#696969) dropped to
     ~2:1. Lift the big values to primary text, the tabs to body text, and all
     the small labels/legends to the readable muted grey. */
  .status.label-xlarge,
  #pollen_section .status,
  #uv_section .status,
  .flu-activity .label {
    color: var(--wu-text) !important;
  }
  .tab-nav a,
  .tab-nav li a,
  ul.tab-nav li a {
    color: var(--wu-text-2) !important;
  }
  .tab-nav li.active a,
  ul.tab-nav li.active a {
    color: var(--wu-text) !important;
  }
  /* The pollen-forecast .tab-nav level indicator draws each Trees/Grass/Weed
     bar's TRACK via a li::before border (#d7d7d7) -- a pseudo-element light
     outline no element-bg/border audit can see, so the empty bars shipped with
     a bright grey outline on the dark tile. Darken the track border; the active
     li::after cyan fill (current pollen level) is semantic and kept. */
  .tab-nav li::before,
  ul.tab-nav li::before {
    border-color: var(--wu-border-2) !important;
  }
  .label-small,
  .label-tiny,
  .label-line,
  .pollen-levels .condition,
  .aq-legend,
  .aq-legend .columns,
  .flu-legend .rating,
  .feels-like-scale .label-tiny,
  .feels-like-scale .label-tiny span,
  .monitors .station-row .columns,
  .monitors .station-row .label-unit {
    color: var(--wu-text-muted) !important;
  }

  /* ---- restore WU's semantic colour SCALES (flattened by our own rules) --- */
  /* The `.data-module *` transparent-neutralizer and the blanket `*` border
     reset above are what make the white module bodies dark -- but they also
     erase every colour WU uses to ENCODE data on the health page. All four of
     these read as a legible dark surface, so no contrast, border or background
     audit flags them; the reading is simply gone. The hexes below are WU's own,
     copied verbatim from its stylesheet, so each scale keeps its meaning. */

  /* (a) air-quality legend: the six-band colour scale under the county map. */
  .aq-legend .rating.good {
    background-color: #5b9f49 !important;
  }
  .aq-legend .rating.moderate {
    background-color: #ffb92f !important;
  }
  .aq-legend .rating.unhealthy-sensitive {
    background-color: #ff8833 !important;
  }
  .aq-legend .rating.unhealthy {
    background-color: #d5202a !important;
  }
  .aq-legend .rating.very-unhealthy {
    background-color: #802674 !important;
  }
  .aq-legend .rating.hazardous {
    background-color: #990008 !important;
  }

  /* (b) AQI callout: a 6px left stripe whose colour IS the current level. */
  .aqi .level-none .aqi-callout {
    border-left-color: var(--wu-text-muted) !important;
  }
  .aqi .level-1 .aqi-callout {
    border-left-color: #5b9f49 !important;
  }
  .aqi .level-2 .aqi-callout {
    border-left-color: #ffb92f !important;
  }
  .aqi .level-3 .aqi-callout {
    border-left-color: #ff8833 !important;
  }
  .aqi .level-4 .aqi-callout {
    border-left-color: #d5202a !important;
  }
  .aqi .level-5 .aqi-callout {
    border-left-color: #802674 !important;
  }
  .aqi .level-6 .aqi-callout {
    border-left-color: #990008 !important;
  }

  /* (c) pollen forecast: each day is a 5-segment column, filled bottom-up.
     WU's empty segment is #d7d7d7 (too light on dark) -> component border;
     the reached segments keep the green -> red scale. */
  /* :nth-child(n) matches every li; it is here to out-specify the blanket
     `.data-module *:not(img)...` neutralizer, which carries five compound
     arguments and otherwise wins this declaration. */
  .pollen-levels .rating li:nth-child(n) {
    background-color: var(--wu-border-2) !important;
  }
  .pollen-levels .high li:nth-child(1) {
    background-color: #d5202a !important;
  }
  .pollen-levels .high li:nth-child(2),
  .pollen-levels .medium-high li:nth-child(2) {
    background-color: #ff8833 !important;
  }
  .pollen-levels .high li:nth-child(3),
  .pollen-levels .medium-high li:nth-child(3),
  .pollen-levels .medium li:nth-child(3) {
    background-color: #ffb92f !important;
  }
  .pollen-levels .high li:nth-child(4),
  .pollen-levels .medium-high li:nth-child(4),
  .pollen-levels .medium li:nth-child(4),
  .pollen-levels .low-medium li:nth-child(4) {
    background-color: #87c404 !important;
  }
  .pollen-levels .high li:nth-child(5),
  .pollen-levels .medium-high li:nth-child(5),
  .pollen-levels .medium li:nth-child(5),
  .pollen-levels .low-medium li:nth-child(5),
  .pollen-levels .low li:nth-child(5) {
    background-color: #5b9f49 !important;
  }

  /* (d) UV skin-type picker: the SELECTED swatch is marked only by a #15aadc
     ring (its white fill is irrelevant on dark). The `*` reset erased it, so
     all three swatches looked identically unselected. */
  .uv-index .skin-types li.active {
    border-color: #15aadc !important;
  }

  /* (e) wind-chill/heat "feels like" scale: a three-band bar reading cold DANGER
     (blue gradient) -> OK (green) -> heat DANGER (orange gradient). The chill/heat
     bands paint their gradients via background-IMAGE (untouched), but the middle
     .scale-ok band is a solid green (#5b9f49) background-COLOR the `.data-module *`
     neutralizer flattened to transparent -- leaving a dark gap where the "you're in
     the safe zone" reading should be. Restore the green; this (0,3,0) prelude clears
     the (0,2,4) blanket. */
  .data-module .feels-like-scale .scale-ok {
    background-color: #5b9f49 !important;
  }

  /* ====================================================================== */
  /* More colour WU encodes in BORDERS, which our blanket `*` reset ate.     */
  /* The reset carries `!important`, so it beats every one of WU's own       */
  /* (non-important) rules below no matter how specific they are -- each of  */
  /* these reads as a legible dark control, so no contrast/bg audit sees it. */
  /* ====================================================================== */

  /* ---- (a) /health UV pyramid ------------------------------------------- */
  /* Each level of the UV pyramid is a CSS-triangle <div class="chunk"> whose
     VALUE is its border-bottom-color (#D7D7D7 unreached; green -> amber ->
     orange -> red -> purple as the index climbs) and whose trapezoid shape
     depends on transparent left/right borders. The `*` reset painted all four
     sides: every level went uniform grey (the entire UV reading, gone) and the
     wedges rendered as plain blocks. Restore WU's scale verbatim. */
  .pyramid .chunk {
    border-bottom-color: var(--wu-border-2) !important;
    border-left-color: transparent !important;
    border-right-color: transparent !important;
  }
  .pyramid .chunk.low {
    border-bottom-color: #5b9f49 !important;
  }
  .pyramid .chunk.moderate {
    border-bottom-color: #ffb92f !important;
  }
  .pyramid .chunk.high {
    border-bottom-color: #ff8833 !important;
  }
  .pyramid .chunk.very-high {
    border-bottom-color: #d5202a !important;
  }
  .pyramid .chunk.extreme {
    border-bottom-color: #ac54a0 !important;
  }

  /* ---- (b) calendar day cells ------------------------------------------- */
  /* WU encodes each cell's DATA KIND on both the cell border and the day
     number: .history = neutral grey (observed), .today = #ff8833 orange,
     .forecast = #008fbf blue. The `*` reset plus our own `.date` muted-grey
     lift flattened all three, so TODAY looked exactly like every other day and
     observed/forecast were indistinguishable. The date text is a link, so the
     forecast blue is lifted to the dark-friendly link blue; the orange and the
     neutral grey read as authored. */
  .calendar-day.today {
    border-color: #ff8833 !important;
  }
  .calendar-day.today .date {
    color: #ff8833 !important;
  }
  .calendar-day.forecast {
    border-color: #008fbf !important;
  }
  .calendar-day.forecast .date {
    color: var(--wu-link) !important;
  }
  .calendar-day.history {
    border-color: var(--wu-border-2) !important;
  }
  .calendar-day.history .date {
    color: var(--wu-text-muted) !important;
  }

  /* ---- (c) header flyout + sidenav menu accents -------------------------- */
  /* The header nav flyouts mark the hovered item with a 6px coloured left bar
     (#ff8833, or the item's own wunder-* hue) -- the item's background does not
     change, so that bar is the ONLY hover affordance, and the `*` reset erased
     it. Click-gated, so no load-time scan reaches it. */
  .mat-mdc-menu-panel.menu-wrapper .mat-mdc-menu-item:hover {
    border-left-color: #ff8833 !important;
  }
  /* The mobile sidenav and the desktop feature-menu carry WU's rainbow code on
     every row (matching the brand strip under the header): Sensor Network red,
     Maps orange, Severe Weather amber, News green, Mobile Apps cyan, Historical
     indigo, and violet. Flattened to grey by the same reset. */
  .sidenav-main-menu-links .mat-mdc-button.wunder-r,
  .feature-menu .mat-mdc-button.wunder-r,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-r {
    border-left-color: #d5202a !important;
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-o,
  .feature-menu .mat-mdc-button.wunder-o,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-o {
    border-left-color: #ff8833 !important;
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-y,
  .feature-menu .mat-mdc-button.wunder-y,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-y {
    border-left-color: #ffb92f !important;
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-g,
  .feature-menu .mat-mdc-button.wunder-g,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-g {
    border-left-color: #5b9f49 !important;
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-b,
  .feature-menu .mat-mdc-button.wunder-b,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-b {
    border-left-color: #15aadc !important;
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-i,
  .sidenav-main-menu-links .mat-mdc-button.more,
  .feature-menu .mat-mdc-button.wunder-i,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-i {
    border-left-color: #2f7fd6 !important;   /* WU's #0053ae, lifted for dark */
  }
  .sidenav-main-menu-links .mat-mdc-button.wunder-v,
  .feature-menu .mat-mdc-button.wunder-v,
  .menu-wrapper .mat-mdc-menu-item:hover.wunder-v {
    border-left-color: #ac54a0 !important;
  }
  /* The DESKTOP header nav is the odd one out: WU marks its hovered/active item
     with a 6px border-TOP (`.feature-menu .mat-mdc-button:hover.wunder-r
     { border-top-color }`), not the left bar the sidenav and the flyout use. The
     rules above only restore border-LEFT-color, and these buttons have
     border-left-width 0, so that restoration never paints -- meanwhile the `*`
     reset flattened the top bar to the line colour and the item's background
     does not change at all, leaving the top-level nav with NO hover affordance.
     Colour the top edge too; at rest its width is 0, so this only shows on
     hover/active exactly as WU intends. */
  .feature-menu .mat-mdc-button:hover.wunder-r,
  .feature-menu .mat-mdc-button.active.wunder-r {
    border-top-color: #d5202a !important;
  }
  .feature-menu .mat-mdc-button:hover.wunder-o,
  .feature-menu .mat-mdc-button.active.wunder-o {
    border-top-color: #ff8833 !important;
  }
  .feature-menu .mat-mdc-button:hover.wunder-y,
  .feature-menu .mat-mdc-button.active.wunder-y {
    border-top-color: #ffb92f !important;
  }
  .feature-menu .mat-mdc-button:hover.wunder-g,
  .feature-menu .mat-mdc-button.active.wunder-g {
    border-top-color: #5b9f49 !important;
  }
  .feature-menu .mat-mdc-button:hover.wunder-b,
  .feature-menu .mat-mdc-button.active.wunder-b {
    border-top-color: #15aadc !important;
  }
  .feature-menu .mat-mdc-button:hover.wunder-i,
  .feature-menu .mat-mdc-button.active.wunder-i,
  .feature-menu .mat-mdc-button:hover.more,
  .feature-menu .mat-mdc-button.active.more {
    border-top-color: #2f7fd6 !important;   /* WU's #0053ae, lifted for dark */
  }
  .feature-menu .mat-mdc-button:hover.wunder-v,
  .feature-menu .mat-mdc-button.active.wunder-v {
    border-top-color: #ac54a0 !important;
  }

  /* ---- (d) Popular Cities bar: hover chip (audit-blind, hover-gated) ----- */
  /* Hovering a city in the favourites bar paints the chip #e7e7e7 -- WU's own
     white hover fill, which we never darkened. Our light link text then lands on
     it at ~1.3:1: the chip you are pointing at is the one you cannot read. */
  .favs li > a:hover,
  .favoritesBar .favs li > a:hover {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* WU paints an even brighter hover on the bar's leading STAR chip
     (`.favorites .favorites-bar .star-wrapper a:hover` -> pure #fff), which the
     city-chip rule above never reached. The star glyph then renders in our light
     link-hover blue on white at ~1.5:1 -- the affordance disappears exactly when you
     point at it. The bar is global chrome, so this is on every page type, and it is
     hover-gated, so no load-time scan reaches it. Darkening the chip is enough: the
     glyph keeps the accent blue it already carries. */
  .favorites .favorites-bar .star-wrapper a:hover,
  .favorites-bar .star-wrapper a:hover {
    background-color: var(--wu-surface-2) !important;
  }

  /* ---- (e) blog / news pagination --------------------------------------- */
  /* The page-number discs are #f7f7f7 (unthemed white) and the CURRENT one is a
     #15aadc disc whose label WU paints white -- our generic `a` lift dropped it
     to link-blue on cyan (~1.9:1). The Prev/Next chevrons are inline <svg> with
     a near-black fill (#1e2023), invisible on dark; only the DISABLED one is
     grey, so painting both alike would erase the disabled state. */
  .pagination a.page-number {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text) !important;
  }
  /* WU's own `.pagination a:hover` (#e7e7e7) carries no `!important`, so the rule
     above beats it and the discs give no hover feedback at all -- restate the tint
     in the dark palette. */
  .pagination a.page-number:hover {
    background-color: var(--wu-border-2) !important;
  }
  .pagination a.page-number.current {
    background-color: #15aadc !important;
    color: #ffffff !important;
  }
  .pagination .btn a,
  .pagination .btn svg,
  .pagination .btn svg path {
    color: var(--wu-text) !important;
    fill: var(--wu-text) !important;
  }
  .pagination .btn.disable a,
  .pagination .btn.disable svg,
  .pagination .btn.disable svg path {
    color: var(--wu-text-muted) !important;
    fill: var(--wu-text-muted) !important;
  }

  /* ---- (f) forecast-tile narrative -------------------------------------- */
  /* Today/Tonight/Tomorrow wrap their whole tile in an <a class="module-link">,
     which WU deliberately paints as BODY TEXT (#1e2023) -- the tile is clickable
     as a whole, not a link to read. Our generic `a` lift turned three paragraphs
     of prose (and the HIGH/LOW/°F labels) link-blue, making them indistinguish-
     able from the real "7% Precip." link directly above them. */
  a.module-link,
  a.module-link .wu-label,
  a.module-link .wu-degree {
    color: var(--wu-text-2) !important;
  }
  a.module-link:hover,
  a.module-link:hover .wu-label {
    color: var(--wu-text) !important;
  }

  /* ---- (g) PWS tile info buttons ---------------------------------------- */
  /* Each dashboard tile header carries a cyan (#15aadc) circled-i tooltip
     button. Our `.mat-mdc-tooltip-trigger` muted-grey rule (meant for WU's grey
     caption text) greyed the icons too, so they stopped reading as controls. */
  i.mat-mdc-tooltip-trigger.material-icons,
  .module__header .mat-mdc-tooltip-trigger {
    color: var(--wu-link) !important;
  }

  /* ---- (h) maps-catalog "MAP SELECT" current map ------------------------ */
  /* The catalog's MAP SELECT grid marks the map you are viewing with a 2px
     #006f9e ring around its thumbnail -- the ONLY cue, since the caption stays
     the same link blue as its siblings. The blanket `*` border reset flattened
     the ring to the generic line colour, so all five tiles looked identical.
     Restore the accent (the ring's width is WU's, we only recolour it). */
  .thumbnail-img.selected {
    border-color: #15aadc !important;
  }

  /* ---- (i) Foundation callouts (hurricane basin activity) --------------- */
  /* `.callout` is Foundation's message box: a #fff panel with near-black ink
     plus five tinted variants that ENCODE severity. Nothing above reaches it,
     so /hurricane's six Basin Activity rows shipped as full-width white bands
     carrying our lifted white heading. Darken the base and restate each tint as
     a dark wash of the same hue so success/warning/alert still read apart. */
  .callout {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .callout.primary {
    background-color: #16303d !important;
  }
  .callout.secondary {
    background-color: var(--wu-surface-2) !important;
  }
  .callout.success {
    background-color: #17301b !important;
  }
  .callout.warning {
    background-color: #3a2a17 !important;
  }
  .callout.alert {
    background-color: #3a1b1e !important;
  }
  /* WU's #696969 inside the callout is ~3:1 on the darkened panel. The
     `.activity` variant is the other half of a two-state pair -- WU paints it
     orange to say this basin HAS storms -- so the mute must stop short of it. */
  .callout .storm-status,
  .callout .storm-status span {
    color: var(--wu-text-muted) !important;
  }
  .callout .storm-status.activity,
  .callout .storm-status.activity span {
    color: #ff8833 !important;
  }

  /* ---- (j) Material expansion panels ------------------------------------ */
  /* mat-expansion-panel keeps Material's own #fff surface and rgba(0,0,0,.87)
     ink, and its chevron is an inline SVG painted through `fill`. The
     /hurricane "Hurricane Resources" accordion is two white slabs on the dark
     page whose bodies are already dark, so the closed panel is the worst case. */
  mat-expansion-panel,
  .mat-expansion-panel,
  mat-expansion-panel-header,
  .mat-expansion-panel-header,
  .mat-expansion-panel-body {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  .mat-expansion-panel-header:hover,
  .mat-expansion-panel-header:focus {
    background-color: var(--wu-surface-2) !important;
  }
  .mat-expansion-panel-header-title,
  .mat-expansion-panel-header-description {
    color: var(--wu-text) !important;
  }
  .mat-expansion-indicator,
  .mat-expansion-indicator svg,
  .mat-expansion-indicator svg path {
    color: var(--wu-text-2) !important;
    fill: var(--wu-text-2) !important;
  }
  /* The indicator's <svg> is display:none -- the chevron actually drawn is the
     ::after, a rotated 8px box with only its right and bottom borders, in
     rgba(0,0,0,.54). `*` never matches a pseudo, so the reset misses it. */
  .mat-expansion-indicator::after {
    border-color: var(--wu-text-2) !important;
  }

  /* ---- (k) module footer CTA -------------------------------------------- */
  /* WU gives every `.basic-module` / `.data-module` a `.footer` strip holding
     the module's one CTA ("Learn More", "View More ..."). It is geometry only
     natively -- transparent, with a #006f9e link. Our page-footer rules match on
     the bare class, so the strip took the chrome fill and the link took plain
     body ink: the CTA reads as a sentence, not a control. */
  .basic-module > .footer,
  .data-module > .footer {
    background-color: transparent !important;
  }
  .basic-module .footer a,
  .data-module .footer a {
    color: var(--wu-link) !important;
  }
  .basic-module .footer a:hover,
  .data-module .footer a:hover {
    color: var(--wu-link-hover) !important;
  }

  /* ---- (l) blockquote --------------------------------------------------- */
  /* WU sets `blockquote, blockquote p { color:#4c4c4c }` globally, so every
     quoted block (the /about/contact-us press + postal addresses) lands
     ~1.3:1 on the dark base. */
  blockquote,
  blockquote p {
    color: var(--wu-text-2) !important;
  }

  /* ---- (m) sign-up opt-in checkbox -------------------------------------- */
  /* The /signup marketing opt-in is the third instance of WU's sprite
     checkbox: a `label.checkbox` whose box is the label's ::before cell of
     wu4Form_sprite.png (solid white when unchecked, a cyan tick when checked)
     and whose own text keeps WU's #1e2023. Both are invisible-class faults --
     the sprite is a bg-image on a pseudo, the label ink is dark-on-dark. */
  label.checkbox,
  label.checkbox span {
    color: var(--wu-text-2) !important;
  }
  label.checkbox::before {
    filter: invert(1) brightness(2.2) !important;
  }
  input:checked + label.checkbox::before {
    filter: none !important;
  }

  /* ---- (n) posters / infographics gallery ------------------------------- */
  /* `.region-content-main` carries an INLINE pastel background WU derives from
     the poster art (`style="background-color:#cedae9"`), so the whole gallery
     column is a pale panel under our lifted light text. The Popular Cities bar
     on these pages is a different component from the city page's
     `.favoritesBar` -- `.favs-wrapper`, an opaque white plate over the poster
     banner -- and keeps its white behind the same light text. */
  .region-content-main {
    background-color: var(--wu-base) !important;
  }
  .favs-container .favs-wrapper,
  .favs-wrapper {
    background-color: var(--wu-chrome) !important;
  }

  /* ---- (o) storm-detail Saffir-Simpson scale ---------------------------- */
  /* The tracker's Storm Category legend is a seven-band colour scale: each
     `.storm-range` cell is filled with WU's category hue and labelled in
     near-black ON that fill. `.storm-range` is also a Foundation `.row`, so the
     grid neutralizer zeroed every fill -- the scale went blank and its labels
     became near-black on the dark card, taking the whole reading with them. The
     `.row.storm-range` prelude is what clears the neutralizer; hexes are WU's. */
  .row.storm-range .trop-depression {
    background-color: #10eefc !important;
  }
  .row.storm-range .trop-storm {
    background-color: #7afc00 !important;
  }
  .row.storm-range .cat-1 {
    background-color: #fcfc00 !important;
  }
  .row.storm-range .cat-2 {
    background-color: #fcab00 !important;
  }
  .row.storm-range .cat-3 {
    background-color: #fa0000 !important;
  }
  .row.storm-range .cat-4 {
    background-color: #fc00fc !important;
  }
  .row.storm-range .cat-5 {
    background-color: #ffc2ff !important;
  }

  /* ====================================================================== */
  /* The second, custom-element frontend ("the new Weather Underground       */
  /* website", currently the /history/* pages).                              */
  /*                                                                         */
  /* It shares nothing with the Angular tree above: its chrome is <header>,   */
  /* action-bar-wc, location-header-view, mobile-nav-wc, search-wc,           */
  /* scale-change-wc and footer-view, so not one selector above reaches it.   */
  /* It ships BOTH palettes behind `prefers-color-scheme`, which our          */
  /* `color-scheme: dark` cannot flip -- under a light OS every surface here  */
  /* is white while our text rules have already lifted the ink off it, so the */
  /* page must be reviewed under both schemes.                                */
  /* ====================================================================== */
  body > header,
  action-bar-wc,
  mobile-nav-wc,
  mobile-nav-wc ol,
  body > header details ol,
  action-bar-wc details ol,
  search-wc ul {
    background-color: var(--wu-chrome) !important;
    color: var(--wu-text-2) !important;
  }
  mobile-nav-wc li,
  mobile-nav-wc a {
    color: var(--wu-text-2) !important;
  }
  /* The narrow-viewport hamburger / close cross is three <span> bars whose
     colour is a background-COLOR keyed to the OS scheme: white under a dark
     OS, #1e2023 under a light one, where it disappears into the header we
     just darkened. It is the only way to open or close the drawer. */
  header-menu-wc .hamburger span {
    background-color: var(--wu-text) !important;
  }
  location-header-view {
    background-color: var(--wu-base) !important;
  }
  location-header-view .elevation-coordinates,
  .high-low-item .label {
    color: var(--wu-text-muted) !important;
  }
  /* Both nav rows keep their accent bar transparent at rest and colour it on
     hover / for the selected tab. The blanket `*` reset paints it at REST too,
     so six permanent grey chips sit above the header nav and the cyan on the
     selected page tab is gone. The header items carry no class -- their hue is
     positional. WU's own hexes, except the last: its #2152a8 is too dark here,
     so it takes the same lift the Angular header's indigo gets. */
  body > header nav details,
  location-header-view nav a {
    border-top-color: transparent !important;
  }
  body > header nav details:nth-of-type(1):hover {
    border-top-color: #c43533 !important;
  }
  body > header nav details:nth-of-type(2):hover {
    border-top-color: #ef8e48 !important;
  }
  body > header nav details:nth-of-type(3):hover {
    border-top-color: #f5bc4f !important;
  }
  body > header nav details:nth-of-type(4):hover {
    border-top-color: #6b9d53 !important;
  }
  body > header nav details:nth-of-type(5):hover {
    border-top-color: #4fa7d7 !important;
  }
  body > header nav details:nth-of-type(6):hover {
    border-top-color: #2f7fd6 !important;
  }
  location-header-view nav a.selected {
    background-color: var(--wu-surface) !important;
    border-top-color: #15aadc !important;
  }
  /* search-wc paints the pill; its <input> only fills the interior. Darkening
     the input alone leaves the host's #e7e7e7 as a light rim, and the
     geolocate button inside is transparent, so it reads as a light chip. */
  search-wc {
    background-color: var(--wu-surface-2) !important;
    border-color: var(--wu-border-2) !important;
  }
  /* The °F/°C scale toggle stays a light #e7e7e7 chip in BOTH palettes, so our
     light button ink lands white-on-white and the selected/unselected pair
     (black vs #4fa7d7) collapses into one blank chip. */
  scale-change-wc button {
    background-color: var(--wu-surface-2) !important;
    color: var(--wu-text-2) !important;
    border-color: var(--wu-border-2) !important;
  }
  scale-change-wc button.selected {
    background-color: #15aadc !important;
    color: #ffffff !important;
    border-color: #15aadc !important;
  }
  /* Daily / Weekly / Monthly: the active pill is white in the light palette,
     which our light button ink erases. */
  .segmented-control {
    background-color: var(--wu-surface-2) !important;
  }
  .segmented-control .toggle-btn {
    color: var(--wu-text-muted) !important;
  }
  .segmented-control .toggle-btn.active {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text) !important;
  }
  /* Its primary buttons ("View", "Go Ad Free") size themselves with
     `border: 3px solid transparent` over the cyan fill, so the blanket `*`
     reset stamps a dark band across the top and bottom of every one. */
  button.blue {
    border-color: transparent !important;
  }
  /* The Glossary is a native <dialog> that ships closed on every /history page.
     It follows the OS scheme like the rest of this frontend, so under a light
     OS it opens as a full white sheet with near-black ink -- and a closed
     dialog has no box, so no load-time scan reaches it. */
  glossary-overlay-view dialog {
    background-color: var(--wu-surface) !important;
    color: var(--wu-text-2) !important;
  }
  glossary-overlay-view .top {
    background-color: var(--wu-surface-2) !important;
  }
  glossary-overlay-view .title,
  glossary-overlay-view .selected {
    color: var(--wu-text) !important;
  }
  glossary-overlay-view li,
  glossary-overlay-view .explanation {
    color: var(--wu-text-2) !important;
  }
  /* The observation cells carry their own fill, which covers the row zebra. */
  .observations-table tbody td {
    background-color: transparent !important;
  }
  /* The Day High / Low readouts are the page's headline numbers and WU ships
     them in its light-page red and blue (#c43533 / #2152a8) in both palettes:
     ~3.3:1 and ~2.4:1 here. Lift to the pair the rest of the theme uses. */
  .high-low-item.high .value {
    color: #ff6b6b !important;
  }
  .high-low-item.low .value {
    color: #4d9fe6 !important;
  }
  /* A `position: fixed` full-viewport overlay that ships hidden and is shown
     for slow date navigations. It takes its fill from the OS palette, so under
     a light OS it flashes the entire page white. Its spinner is a
     background-IMAGE with no dark variant under a light OS, which is what the
     invert below is for -- that invert only reads as a spinner because this
     rule puts a dark ground under it in both schemes. */
  long-load-view {
    background-color: var(--wu-base) !important;
  }
  /* This frontend swaps to a `-dark` suffixed copy of every monochrome icon
     under `prefers-color-scheme: dark` only, and that media query answers to
     the OS, not to our `color-scheme`. So under a LIGHT OS it keeps serving
     the near-black glyph set as background-IMAGES -- unreachable by any fill
     or colour rule -- on the chrome we just darkened. Each of these elements
     is empty, so inverting the box only inverts the glyph. `mobile-nav-wc
     li.settings` is deliberately absent: its glyph shares the box with the
     row's label, so a filter there would flip the text too. */
  @media (prefers-color-scheme: light) {
    action-bar-wc details.settings summary,
    span.icon.airport,
    span.chart-section-toggle,
    glossary-overlay-view .close,
    long-load-view .loader {
      filter: invert(1) !important;
    }
    /* The header logo is one box carrying BOTH the rainbow WU mark and the
       wordmark, and only the wordmark changes between the two assets: the
       light copy paints it #1e2023, which is 1.1:1 on the header we darkened,
       so the brand name is simply absent. A filter on the box recolours the
       mark too (invert alone turns the red W cyan; adding hue-rotate turns it
       brown), so overlay an inverted copy of the SAME image clipped to the
       wordmark. `background-image: inherit` resolves to whatever hashed URL
       the current build serves, so no asset URL is pinned here. */
    body > header a.logo {
      position: relative;
    }
    body > header a.logo::after {
      content: "";
      position: absolute;
      top: 0;
      right: 0;
      bottom: 0;
      left: 28%;                      /* starts clear of the rainbow WU mark */
      background-image: inherit;
      background-repeat: no-repeat;
      background-size: 138.9% 100%;   /* 1/0.72: redraw at the host's scale */
      background-position: right center;
      filter: invert(1);
    }
  }
}
